insert into public.needs
  (ministry_id, title, type, urgency, people, focus, remote, commitment, skills, detail, posted, status)
select m.id, v.title, v.type, v.urgency, v.people, v.focus, v.remote, v.commitment, v.skills, v.detail, v.posted::date, 'live'
from (values
  ('w-tokyo-discipleship-fellowship', 'Podcast producer', 'volunteers', 'soon', 1, 'media', true, '3 hrs/episode · 6 episodes', array['Audio editing', 'Podcasting']::text[], 'Our pastors in Tokyo record short teaching episodes on their phones. Clean up the audio and publish them each fortnight.', '2026-08-08'),
  ('w-tokyo-discipleship-fellowship', 'Social media volunteer', 'volunteers', 'urgent', 1, 'media', true, '2 hrs/week · 3 months', array['Instagram', 'Facebook', 'Copywriting']::text[], 'Turn the photos and stories our team sends from Tokyo into two or three posts a week, and keep the replies answered.', '2026-08-31'),
  ('w-tokyo-discipleship-fellowship', 'Trauma-informed care training', 'expertise', 'soon', 1, 'trauma', true, '10 hrs total', array['Counselling', 'Training design']::text[], 'Our volunteers in Tokyo hear hard stories every week. We want a short video course on listening well and looking after themselves.', '2026-10-03'),
  ('w-tokyo-discipleship-fellowship', 'Photo editor', 'volunteers', 'urgent', 1, 'media', true, '2 hrs/week · 2 months', array['Photo editing', 'Lightroom']::text[], 'We take hundreds of photos of our work in Tokyo and use none of them. Help us choose, edit and caption a library we can use for a year.', '2026-06-08'),
  ('w-tokyo-discipleship-fellowship', 'Curriculum writer for discipleship', 'expertise', 'ongoing', 1, 'discipleship', true, '15 hrs total', array['Curriculum design', 'Teaching']::text[], 'We run small groups, leadership training and support for pastors serving without pay. We want a twelve-week programme our volunteers can lead without us, written simply enough to translate into Japanese.', '2026-08-25'),
  ('w-tokyo-discipleship-fellowship', 'Volunteer coordinator (remote)', 'volunteers', 'urgent', 1, 'admin', true, '2 hrs/week · ongoing', array['Scheduling', 'WhatsApp', 'Google Sheets']::text[], 'Keep our volunteer rota in Tokyo running from home: scheduling, reminders and a monthly thank-you.', '2026-07-28'),
  ('w-tokyo-discipleship-fellowship', 'Database clean-up', 'volunteers', 'ongoing', 1, 'admin', true, '10 hrs total', array['Spreadsheets', 'Attention to detail']::text[], 'Our list of families and donors lives in four spreadsheets that disagree. Merge them into one we can trust.', '2026-05-13'),
  ('w-new-york-community-kitchen', 'Bookkeeping set-up', 'expertise', 'ongoing', 1, 'admin', true, '8 hrs total', array['Bookkeeping', 'Spreadsheets']::text[], 'A simple, honest set of books: a spreadsheet template, a monthly routine, and one video call to walk our treasurer through it.', '2026-10-04'),
  ('w-new-york-community-kitchen', 'Photo editor', 'volunteers', 'ongoing', 1, 'media', true, '2 hrs/week · 2 months', array['Photo editing', 'Lightroom']::text[], 'We take hundreds of photos of our work in New York and use none of them. Help us choose, edit and caption a library we can use for a year.', '2026-07-30'),
  ('w-new-york-community-kitchen', 'Grant application writer', 'expertise', 'soon', 1, 'fundraising', true, '20 hrs · two applications', array['Grant writing', 'English']::text[], 'We have the budget and the reports from our work in New York; we need someone who has written foundation applications before to make the case clearly.', '2026-07-20'),
  ('w-new-york-community-kitchen', 'Legal advice on registration', 'expertise', 'urgent', 1, 'legal', true, '6 hrs total', array['Non-profit law', 'United States of America law helpful']::text[], 'We are registering as a charity in United States of America and want someone to check our constitution and governance before we file.', '2026-05-25'),
  ('w-new-york-community-kitchen', 'Small business mentors', 'volunteers', 'ongoing', 3, 'work', true, '1 hr/fortnight · 6 months', array['Small business', 'Mentoring']::text[], 'Women in our savings groups in New York are starting small businesses. Each needs one mentor, by video, every other week.', '2026-09-30'),
  ('w-new-york-community-kitchen', 'Remote IT support', 'expertise', 'soon', 1, 'technology', true, '3 hrs/week · 3 months', array['IT support', 'Google Workspace or Microsoft 365']::text[], 'Someone our staff in New York can message when the laptops, email or shared drive stop working, and who can set things up so they stop breaking.', '2026-08-28'),
  ('w-new-york-community-kitchen', 'Logo and visual identity', 'expertise', 'urgent', 1, 'design', true, '8 hrs total · 3 weeks', array['Logo design', 'Branding']::text[], 'We have outgrown a logo made in a word processor. A simple mark, two colours and a one-page guide we can hand to a print shop in New York.', '2026-06-20'),
  ('w-mexico-city-wells-taps-network', 'Laptops for a computer class', 'supplies', 'ongoing', 0, 'technology', true, 'One-off', array['Donated laptops', 'Shipping help']::text[], 'Ten working laptops for a basic computer class in Mexico City. Refurbished is fine; we can arrange collection from a partner office.', '2026-08-11'),
  ('w-mexico-city-wells-taps-network', 'Grant application writer', 'expertise', 'ongoing', 1, 'fundraising', true, '15 hrs · one application', array['Grant writing', 'English']::text[], 'We have the budget and the reports from our work in Mexico City; we need someone who has written foundation applications before to make the case clearly.', '2026-09-08'),
  ('w-mexico-city-wells-taps-network', 'Partner church for prayer and support', 'partners', 'urgent', 0, 'discipleship', true, 'Ongoing', array['A church or small group']::text[], 'A church elsewhere in the world to pray with our team in Mexico City, meet by video each quarter and walk with us for the long term.', '2026-06-28'),
  ('w-mexico-city-wells-taps-network', 'Telehealth doctor adviser', 'expertise', 'urgent', 1, 'health', true, '2 hrs/week · 3 months', array['Medicine', 'Telehealth']::text[], 'A doctor our nurses in Mexico City can consult by video on the cases they are unsure of, so fewer families make the long trip to hospital for nothing.', '2026-05-20'),
  ('w-mexico-city-wells-taps-network', 'Worship team mentor', 'volunteers', 'soon', 1, 'worship', true, '1 hr/week · 3 months', array['Music', 'Worship leading']::text[], 'Our young worship team in Mexico City is keen and untrained. A weekly video call on arranging, rehearsing and leading well.', '2026-09-09'),
  ('w-mexico-city-wells-taps-network', 'Funding for a water tank', 'funding', 'soon', 0, 'water', true, 'One-off · by year end', array['Giving', 'Fundraising']::text[], 'One 10,000-litre tank and the guttering to fill it, for a neighbourhood in Mexico City that buys water by the jerrycan.', '2026-05-18'),
  ('w-mexico-city-wells-taps-network', 'Remote IT support', 'expertise', 'soon', 1, 'technology', true, '3 hrs/week · 3 months', array['IT support', 'Google Workspace or Microsoft 365']::text[], 'Someone our staff in Mexico City can message when the laptops, email or shared drive stop working, and who can set things up so they stop breaking.', '2026-08-27'),
  ('w-mexico-city-wells-taps-network', 'Legal advice on registration', 'expertise', 'soon', 1, 'legal', true, '4 hrs total', array['Non-profit law', 'Mexico law helpful']::text[], 'We are registering as a charity in Mexico and want someone to check our constitution and governance before we file.', '2026-06-06'),
  ('w-delhi-food-bank', 'HR policy review', 'expertise', 'soon', 1, 'legal', true, '8 hrs total', array['HR', 'Employment policy']::text[], 'We have grown to 11 staff without a proper handbook. A review of what we have and a plain set of policies that fit India.', '2026-06-16'),
  ('w-delhi-food-bank', 'Child safeguarding policy', 'expertise', 'urgent', 1, 'legal', true, '8 hrs total', array['Safeguarding', 'Policy writing']::text[], 'A safeguarding policy and short training for everyone who works with children in our programmes in Delhi, fit for India.', '2026-07-03'),
  ('w-delhi-food-bank', 'Donor newsletter writer', 'volunteers', 'ongoing', 1, 'fundraising', true, '3 hrs/month · 6 months', array['Writing', 'Mailchimp']::text[], 'A short monthly email to our supporters: what happened in Delhi, one story, one ask. We send notes and photos; you make them read well.', '2026-08-17'),
  ('w-delhi-food-bank', 'Strategic plan facilitator', 'expertise', 'urgent', 1, 'leadership', true, '4 sessions · 1 month', array['Strategy', 'Facilitation']::text[], 'Our board wants a three-year plan that the team in Delhi actually believes in. Four video workshops and a written plan at the end.', '2026-06-22'),
  ('w-delhi-food-bank', 'Funding for a water tank', 'funding', 'soon', 0, 'water', true, 'One-off · by year end', array['Giving', 'Fundraising']::text[], 'One 10,000-litre tank and the guttering to fill it, for a neighbourhood in Delhi that buys water by the jerrycan.', '2026-09-17'),
